import { promises as fs } from "fs";
import path from "path";

const DIR = path.join(process.cwd(), "src", "data", "react-guide");

/**
 * README body of the installed `@suneditor/suneditor-react`, translated per locale
 * (generated by `scripts/generate-react-guide.cjs` + `scripts/translate-react-guide.cjs`).
 * Falls back to English when a locale file is missing.
 */
export async function getReactGuide(locale: string): Promise<string | null> {
	const candidates = locale === "en" ? ["en"] : [locale, "en"];
	for (const l of candidates) {
		try {
			return await fs.readFile(path.join(DIR, `react-guide.${l}.md`), "utf-8");
		} catch {
			// try the next candidate
		}
	}
	return null;
}
